import React, { useState, useEffect, useContext, useCallback } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { AuthContext } from '../context/AuthContext';

const Tasks = () => {
  const { projectId } = useParams();
  const [tasks, setTasks] = useState([]);
  const [form, setForm] = useState({ title: '', description: '', assignedTo: '', dueDate: '' });
  const [project, setProject] = useState(null);
  const { user } = useContext(AuthContext);

  useEffect(() => {
    fetchTasks();
    fetchProject();
  }, [projectId, fetchTasks, fetchProject]);

  const fetchTasks = async () => {
    try {
      const res = await axios.get(`/api/tasks/project/${projectId}`);
      setTasks(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchProject = async () => {
    try {
      const res = await axios.get('/api/projects');
      const proj = res.data.find(p => p._id === projectId);
      setProject(proj);
    } catch (err) {
      console.error(err);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post('/api/tasks', { ...form, project: projectId });
      setForm({ title: '', description: '', assignedTo: '', dueDate: '' });
      fetchTasks();
    } catch (err) {
      alert('Failed to create task');
    }
  };

  const updateStatus = async (id, status) => {
    try {
      await axios.put(`/api/tasks/${id}`, { status });
      fetchTasks();
    } catch (err) {
      alert('Failed to update task');
    }
  };

  const deleteTask = async (id) => {
    try {
      await axios.delete(`/api/tasks/${id}`);
      fetchTasks();
    } catch (err) {
      alert('Failed to delete task');
    }
  };

  return (
    <div>
      <h1>Tasks for Project</h1>
      {user?.role === 'Admin' && (
        <form onSubmit={handleSubmit}>
          <input
            type="text"
            placeholder="Task Title"
            value={form.title}
            onChange={(e) => setForm({ ...form, title: e.target.value })}
            required
          />
          <textarea
            placeholder="Description"
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
          />
          <select value={form.assignedTo} onChange={(e) => setForm({ ...form, assignedTo: e.target.value })}>
            <option value="">Unassigned</option>
            {project?.members.map(member => (
              <option key={member._id} value={member._id}>{member.name}</option>
            ))}
          </select>
          <input
            type="date"
            value={form.dueDate}
            onChange={(e) => setForm({ ...form, dueDate: e.target.value })}
          />
          <button type="submit">Create Task</button>
        </form>
      )}
      <ul>
        {tasks.map(task => (
          <li key={task._id}>
            <h3>{task.title}</h3>
            <p>{task.description}</p>
            <p>Status: {task.status}</p>
            <p>Assigned to: {task.assignedTo?.name}</p>
            <p>Due: {task.dueDate ? new Date(task.dueDate).toLocaleDateString() : 'N/A'}</p>
            {(user?.role === 'Admin' || task.assignedTo?._id === user?.id) && (
              <select value={task.status} onChange={(e) => updateStatus(task._id, e.target.value)}>
                <option value="Pending">Pending</option>
                <option value="In Progress">In Progress</option>
                <option value="Completed">Completed</option>
              </select>
            )}
            {user?.role === 'Admin' && (
              <button onClick={() => deleteTask(task._id)}>Delete</button>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default Tasks;
